// Deterministic checks on NomosAI output. The model is told the rules in the
// system prompt; this module verifies them so a slip never reaches the client.

export const AUDIT_FOOTER =
  "Draft generated by NomosAI for final review, verification, and execution by the attorney of record.";

export const FORBIDDEN_PHRASES = [
  // English blacklist from the system prompt
  "in today's fast-paced world",
  "in the ever-evolving landscape",
  "it is imperative to highlight",
  "it is worth noting that",
  "needless to say",
  "crucial",
  "pivotal",
  "invaluable",
  "delve into",
  "beacon",
  "in summary",
  "in conclusion",
  "to summarize",
  "as an ai language model",
  "sure, here is",
  "below is the requested",
  // Spanish equivalents
  "en el mundo actual",
  "cabe destacar",
  "es importante resaltar",
  "vale la pena mencionar",
  "ni que decir tiene",
  "crucial",
  "ahondar en",
  "en resumen",
  "en conclusión",
  "como modelo de lenguaje",
  "claro, aquí tienes",
  "a continuación se presenta",
];

const SECTION_2 = /^\s*(?:#+\s*)?(?:\*\*)?SECTION 2\b.*$/im;
const SECTION_1 = /^\s*(?:#+\s*)?(?:\*\*)?SECTION 1\b.*$/im;
const JSON_BLOCK = /```json\s*([\s\S]*?)```/i;
const FILL_MARKER = /\[FILL:\s*([^\]]+)\]/g;

/** Split raw model text into the document markdown and the JSON payload. */
export function splitSections(raw) {
  const text = raw.replace(/\r\n/g, "\n");
  const s2 = text.match(SECTION_2);
  let docPart = s2 ? text.slice(0, s2.index) : text;
  const jsonPart = s2 ? text.slice(s2.index) : text;

  const s1 = docPart.match(SECTION_1);
  if (s1) docPart = docPart.slice(s1.index + s1[0].length);

  let payload = null;
  let payloadError = null;
  const block = jsonPart.match(JSON_BLOCK);
  if (!block) {
    payloadError = "No ```json block found in SECTION 2.";
  } else {
    try {
      payload = JSON.parse(block[1]);
    } catch (err) {
      payloadError = `JSON payload did not parse: ${err.message}`;
    }
    // Without a SECTION 2 marker, keep the JSON block out of the document.
    if (!s2) docPart = docPart.replace(block[0], "");
  }

  return { document: docPart.trim(), payload, payloadError };
}

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** Run every rule check and return a report the UI can render. */
export function auditDraft(raw, { transactionId } = {}) {
  const { document, payload, payloadError } = splitSections(raw);
  const lower = document.toLowerCase();
  const issues = [];

  const forbidden = [...new Set(FORBIDDEN_PHRASES)].filter((p) =>
    new RegExp(`(^|[^\\p{L}])${escapeRegExp(p)}($|[^\\p{L}])`, "u").test(lower),
  );
  if (forbidden.length) {
    issues.push({ level: "error", code: "FORBIDDEN_PHRASE", detail: forbidden.join(", ") });
  }

  if (!document.includes(AUDIT_FOOTER)) {
    issues.push({ level: "error", code: "MISSING_AUDIT_FOOTER", detail: AUDIT_FOOTER });
  }

  for (const field of ["[OTP_VERIFICATION_CODE]", "[TIMESTAMP]", "[IP_ADDRESS]"]) {
    if (!document.includes(field)) {
      issues.push({ level: "warning", code: "MISSING_ESIGN_FIELD", detail: field });
    }
  }

  if (payloadError) {
    issues.push({ level: "error", code: "PAYLOAD_INVALID", detail: payloadError });
  }

  if (transactionId && payload?.payment_required) {
    if (payload.bold_transaction_id !== transactionId) {
      issues.push({
        level: "error",
        code: "BOLD_ID_MISMATCH",
        detail: `Expected ${transactionId}, got ${payload.bold_transaction_id}`,
      });
    }
    if (!document.includes(`https://checkout.bold.co/payment/link/${transactionId}`)) {
      issues.push({ level: "warning", code: "BOLD_LINK_MISSING", detail: transactionId });
    }
  }

  const fillFields = [...document.matchAll(FILL_MARKER)].map((m) => m[1].trim());

  return {
    document,
    payload,
    fillFields: [...new Set(fillFields)],
    issues,
    ok: !issues.some((i) => i.level === "error"),
  };
}
